import React, { useState } from 'react';
import CustomerList from './components/CustomerList';
import CustomerRegistrationForm from './components/CustomerRegistrationForm';
import CustomerDetails from './components/CustomerDetails';
import './App.css';
import { SignedIn, SignedOut, SignInButton, UserButton } from '@clerk/clerk-react';

// Inline Home page component:
function HomePage() {
  return (
    <div className="home-main">
      <div className="home-hero">
        <span className="crm-logo" role="img" aria-label="CRM">📊</span>
        <h2>Welcome to the CRM Dashboard</h2>
        <p>
          Effortlessly register, manage, and engage with your customers.<br />
          Track interactions, boost sales and customer satisfaction!
        </p>
      </div>
      <div className="home-features">
        <div>
          <h4>👥 Customer Management</h4>
          <p>Organize and store all customer profiles and information.</p>
        </div>
        <div>
          <h4>📄 Interaction Tracking</h4>
          <p>Log inquiries, purchases, complaints, and returns in one place.</p>
        </div>
        <div>
          <h4>📈 Analytics Ready</h4>
          <p>Built for insights and business growth optimization.</p>
        </div>
      </div>
    </div>
  );
}

function App() {
  const [selectedCustomerId, setSelectedCustomerId] = useState(null);
  const [refreshList, setRefreshList] = useState(false);
  const [currentPage, setCurrentPage] = useState('home'); // "home" or "customers"

  return (
    <div className="app-container">
      {/* Signed-in state */}
      <SignedIn>
        <header className="app-header">
          <span className="login-btn">
            <UserButton />
          </span>
          <h1 className="glitter-title">CRM System</h1>
          <nav className="nav-tabs">
            <button
              className={currentPage === 'home' ? 'nav-tab active' : 'nav-tab'}
              onClick={() => {
                setCurrentPage('home');
                setSelectedCustomerId(null);
              }}
            >
              Home
            </button>
            <button
              className={currentPage === 'customers' ? 'nav-tab active' : 'nav-tab'}
              onClick={() => {
                setCurrentPage('customers');
                setSelectedCustomerId(null);
              }}
            >
              Customers
            </button>
          </nav>
        </header>

        <main>
          {currentPage === 'home' ? (
            <HomePage />
          ) : !selectedCustomerId ? (
            <div className="content">
              <div className="form-container">
                <CustomerRegistrationForm onCreate={() => setRefreshList(!refreshList)} />
              </div>
              <div style={{ width: '2rem' }} />
              <div className="table-container">
                <CustomerList
                  key={refreshList}
                  onSelect={setSelectedCustomerId}
                />
              </div>
            </div>
          ) : (
            <div className="content">
              <div className="form-container" style={{ width: '100%' }}>
                <CustomerDetails
                  customerId={selectedCustomerId}
                  onBack={() => setSelectedCustomerId(null)}
                />
              </div>
            </div>
          )}
        </main>
      </SignedIn>

      {/* Signed-out state (no changes) */}
      <SignedOut>
        <div className="center-container">
          <h1 className="glitter-title">CRM SYSTEM</h1>
          <div className="glass-card">
            <div
              style={{
                textAlign: 'center',
                fontSize: '2.5rem',
                marginBottom: '.7rem'
              }}
            >
              🔐
            </div>
            <h2>Welcome to CRM</h2>
            <SignInButton mode="modal">
              <button className="sign-in-btn">Sign In</button>
            </SignInButton>
          </div>
        </div>
      </SignedOut>
    </div>
  );
}

export default App;
